/**
 * Calculate the Levenshtein distance between two strings.
 * @param {string} a - First string
 * @param {string} b - Second string
 * @returns {number} The edit distance between a and b
 */
function levenshteinDistance(a, b) {
  const m = a.length;
  const n = b.length;

  // Create a matrix to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Initialize base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,      // deletion
        dp[i][j - 1] + 1,      // insertion
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Find the closest matching property name from available properties.
 * @param {string} missingProperty - The property name that was not found
 * @param {string[]} availableProperties - List of available property names
 * @returns {string|null} The closest matching property name, or null if no close match
 */
function findClosestMatch(missingProperty, availableProperties) {
  let bestMatch = null;
  let bestDistance = Infinity;

  for (const prop of availableProperties) {
    const distance = levenshteinDistance(missingProperty, prop);

    if (distance <= 3) {
      if (distance < bestDistance) {
        bestDistance = distance;
        bestMatch = prop;
      } else if (distance === bestDistance && prop < bestMatch) {
        // Tie-break alphabetically
        bestMatch = prop;
      }
    }
  }

  return bestMatch;
}

/**
 * Creates a debug helper for a given ViewModel.
 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} A debug helper object with diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  const availableProperties = Object.keys(viewModel).sort();

  return {
    /**
     * Diagnoses a missing property binding error.
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {Object} Diagnosis result with error info, available properties, and suggestions
     */
    diagnoseMissingProperty(propertyName) {
      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: findClosestMatch(propertyName, availableProperties)
      };
    }
  };
}

// Export both the helper factory and the Levenshtein function for testing
module.exports = {
  createDebugHelper,
  levenshteinDistance,
  findClosestMatch
};"}

