const createDebugHelper = require('./ko-debug').createDebugHelper;

// Define a sample ViewModel
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

const helper = createDebugHelper(sampleViewModel);

let allPassed = true;

function runTest(description, actual, expected) {
  if (actual === expected) {
    console.log(`PASS: ${description}`);
  } else {
    console.log(`FAIL: ${description}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
    allPassed = false;
  }
}

// Test 1: Diagnose missing property "item" (should suggest "items")
console.log('\n--- Test Case 1: "item" should suggest "items" ---');
const result1 = helper.diagnoseMissingProperty('item');
runTest('Missing property is "item"', result1.missingProperty, 'item');
runTest('Suggestion is "items"', result1.suggestion, 'items');
runTest('Error flag is true', result1.error, true);
runTest('availableProperties is sorted', 
  JSON.stringify(result1.availableProperties), 
  JSON.stringify(['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount']));

